import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick }) {
  const menuItems = [
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ 
      width: '260px', 
      backgroundColor: '#15803d', 
      color: '#ffffff', 
      padding: '25px 15px', 
      display: 'flex', 
      flexDirection: 'column', 
      justifyContent: 'space-between',
      alignSelf: 'stretch', 
      boxSizing: 'border-box'
    }}>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <div style={{ padding: '0 15px 20px 15px', borderBottom: '1px solid rgba(255,255,255,0.15)', marginBottom: '15px' }}>
          <span style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.5px' }}>📌 Admin Panel</span>
        </div>

        {menuItems.map((item, i) => {
          const isActive = currentSubPage === item.name;
          return (
            <div 
              key={i} 
              onClick={() => setCurrentSubPage(item.name)}
              style={{ 
                padding: '14px 18px', 
                borderRadius: '8px', 
                cursor: 'pointer', 
                display: 'flex', 
                alignItems: 'center', 
                gap: '12px', 
                backgroundColor: isActive ? '#166534' : 'transparent', 
                fontWeight: isActive ? '700' : '500',
                transition: 'all 0.2s'
              }}
            >
              <span style={{ fontSize: '16px' }}>{item.icon}</span> 
              <span style={{ fontSize: '14px' }}>{item.name}</span>
            </div>
          );
        })}
      </div>

      
    </div>
  );
}
